    "explanation": "1. CONCEPT:\nApplication of the parallax method for astronomical distances.\n\n2. GIVEN:\nParallax method.\n\n3. FORMULA / PRINCIPLE:\nDistance D = b / θ, where b is the basis (baseline) and θ is the parallax angle in radians.\n\n4. STEP-BY-STEP SOLUTION:\n1. Parallax is the apparent shift in the position of an object when viewed from two different positions.\n2. The distance between the two points of observation is called the basis (b).\n3. By measuring the angle θ subtended by the basis at the distant celestial object, the distance D is calculated as D = b / θ.\n4. This indirect triangulation method is used to measure distances of planets and nearby stars.\n\n5. FINAL ANSWER:\nOption A: Large distances of distant stars and planets\n\n6. QUICK TIP:\nNEET NCERT Definition: Parallax method = Indirect triangulation used to measure HUGE astronomical distances (planets, stars)!",
