    "correctIndex": 0,
    "explanation": "1. CONCEPT:\nGeneralized algebraic expression for Vernier least count.\n\n2. GIVEN:\n1 MSD = a. n VSD = m MSD.\n\n3. FORMULA / PRINCIPLE:\n1 VSD = (m / n) MSD = (m / n) a. LC = 1 MSD - 1 VSD = a - (m / n) a = a (1 - m / n).\n\n4. STEP-BY-STEP SOLUTION:\n1. By definition, 1 MSD = a.\n2. Given: n VSD = m MSD  =>  1 VSD = (m / n) MSD = (m / n) a.\n3. Least count LC = 1 MSD - 1 VSD = a - (m / n) a.\n4. Factoring out a: LC = a (1 - m / n) = a (n - m) / n.\n5. When m = n - 1, this reduces to standard a / n.\n\n5. FINAL ANSWER:\nOption A: a (1 - m / n)\n\n6. QUICK TIP:\nNEET Generalized Formula: LC = (1 - m/n) MSD = a (1 - m/n). Master this general form!",
