    "question": "A student measures the thickness of a glass slab using a Vernier caliper with 0.1 mm least count. The main scale reading is 15 mm. The 3rd Vernier division coincides. The absolute error in this single reading is equal to the least count (±0.1 mm). The percentage error in the thickness measurement is:",
