    "explanation": "1. CONCEPT:\nDetermining negative zero error using (N - n) rule.\n\n2. GIVEN:\nVernier zero lies to the LEFT of main scale zero. Total Vernier divisions N = 10. Coinciding division n = 6. LC = 0.1 mm.\n\n3. FORMULA / PRINCIPLE:\nNegative Zero Error = - (N - n) × LC = - (10 - 6) × 0.1 mm = - 4 × 0.1 mm = -0.4 mm.\n\n4. STEP-BY-STEP SOLUTION:\n1. Because the Vernier zero is to the left of the main scale zero, the error is NEGATIVE (-).\n2. For negative zero error, we do NOT take the coinciding mark n directly! We must count from the right-hand end of the Vernier scale: (N - n).\n3. Number of divisions from end = 10 - 6 = 4 divisions.\n4. Negative Zero Error = - (10 - 6) × LC = - 4 × 0.1 mm = -0.4 mm = -0.04 cm.\n5. (The zero correction is +0.4 mm).\n\n5. FINAL ANSWER:\nOption A: -0.4 mm (-0.04 cm)\n\n6. QUICK TIP:\nNEET High-Yield Trap Alert: For NEGATIVE zero error: Error = - (Total divisions - Coinciding division) × LC = - (10 - 6) × 0.1 = -0.4 mm! Do NOT write -0.6 mm!",
