      "formula": "Systematic errors are constant, reproducible, and unidirectional.",
      "stepByStep": "1. Zero error is caused by a permanent physical defect in the scale alignment or wear of the contact faces.\n2. As long as the instrument is intact, every single measurement taken with it is shifted by the EXACT same offset in the exact same direction (+e or -e).\n3. It does not fluctuate unpredictably from reading to reading.\n4. Because it is constant and predictable, it can be calibrated and removed completely by algebraic subtraction.\n5. Therefore, it is strictly a Systematic Error.",
