    "correctIndex": 0,
    "explanation": "1. CONCEPT:\nOrigin and prevention of backlash error in screw gauges.\n\n2. GIVEN:\nBacklash error.\n\n3. FORMULA / PRINCIPLE:\nBacklash error arises from play or looseness between the internal screw and external nut threads.\n\n4. STEP-BY-STEP SOLUTION:\n1. Due to repeated wear and tear, the threads of the screw and nut develop mechanical play (space).\n2. When rotation is reversed, the screw rotates slightly without producing linear movement.\n3. This error is avoided by turning the ratchet in one direction continuously during measurement.\n\n5. FINAL ANSWER:\nOption A: Wear and tear of the screw threads leading to loose fitting\n\n6. QUICK TIP:\nNEET Practical Tip: Backlash error = thread play/wear. Always rotate the thimble in one direction only!",
