    "explanation": "1. CONCEPT:\nPercentage error propagation in sphere density calculation.\n\n2. GIVEN:\nΔM/M × 100% = 1.5%, ΔR/R × 100% = 1.0%.\n\n3. FORMULA / PRINCIPLE:\nDensity ρ = M / ((4/3)π R³) => Δρ/ρ = ΔM/M + 3(ΔR/R).\n\n4. STEP-BY-STEP SOLUTION:\n1. Volume of sphere V = (4/3) π R³.\n2. Density ρ = M / V = M / ((4/3) π R³).\n3. Fractional error formula: Δρ/ρ = ΔM/M + 3 (ΔR/R).\n4. In terms of percentage error:\n   % error in ρ = (% error in M) + 3 × (% error in R)\n                = 1.5% + 3 × (1.0%)\n                = 1.5% + 3.0% = 4.5%.\n\n5. FINAL ANSWER:\nOption A: 4.5%\n\n6. QUICK TIP:\nNEET High-Yield: Power of radius is 3! % error in ρ = % error in M + 3 × (% error in R) = 1.5 + 3(1) = 4.5%.",
