    "questionNumber": 474,
    "question": "In a calorimetry experiment, heat absorbed is Q = m c Δθ. The percentage errors in measuring heat Q, mass m, and temperature rise Δθ are 2%, 1%, and 2% respectively. The percentage error in the specific heat capacity c is:",
    "options": {
      "A": "5%",
      "B": "1%",
      "C": "3%",
      "D": "4%"
    },
    "optionsList": [
      "5%",
      "1%",
      "3%",
      "4%"
    ],
    "correctAnswer": "A",
    "correctIndex": 0,
    "explanation": "1. CONCEPT:\nSpecific heat capacity error combination.\n\n2. GIVEN:\n% error in Q = 2%, % error in m = 1%, % error in Δθ = 2%.\n\n3. FORMULA / PRINCIPLE:\nc = Q / (m Δθ) => Δc/c = ΔQ/Q + Δm/m + Δ(Δθ)/Δθ.\n\n4. STEP-BY-STEP SOLUTION:\n1. Express specific heat capacity: c = Q / (m · Δθ).\n2. Maximum fractional error: Δc/c = ΔQ/Q + Δm/m + Δ(Δθ)/Δθ.\n3. Percentage error in c = 2% + 1% + 2% = 5%.\n\n5. FINAL ANSWER:\nOption A: 5%\n\n6. QUICK TIP:\nNEET Principle: All terms in quotient contribute positively to MAXIMUM error: 2% + 1% + 2% = 5%.",
    "solutionStructured": {
      "concept": "Specific heat capacity error combination.",
      "given": "% error in Q = 2%, % error in m = 1%, % error in Δθ = 2%.",
      "formula": "c = Q / (m Δθ) => Δc/c = ΔQ/Q + Δm/m + Δ(Δθ)/Δθ.",
      "stepByStep": "1. Express specific heat capacity: c = Q / (m · Δθ).\n2. Maximum fractional error: Δc/c = ΔQ/Q + Δm/m + Δ(Δθ)/Δθ.\n3. Percentage error in c = 2% + 1% + 2% = 5%.",
      "finalAnswer": "Option A: 5%",
      "whyOtherOptionsWrong": "Option B subtracts errors (2 - 1). Option C cancels out terms. Option D misses one term."
    },
