    "id": "um-mcq-478",
    "questionNumber": 478,
    "question": "The coefficient of viscosity η of a liquid flowing through a capillary tube is given by Poiseuille's formula: η = (π P r⁴) / (8 V l). Which measured physical quantity contributes the greatest relative error to η?",
    "options": {
      "A": "Radius of the capillary tube (r)",
      "B": "Pressure difference (P)",
      "C": "Length of the tube (l)",
      "D": "Rate of liquid flow (V)"
    },
    "optionsList": [
      "Radius of the capillary tube (r)",
      "Pressure difference (P)",
      "Length of the tube (l)",
      "Rate of liquid flow (V)"
    ],
    "correctAnswer": "A",
    "correctIndex": 0,
    "explanation": "1. CONCEPT:\nDominant error contribution in Poiseuille's viscosity equation.\n\n2. GIVEN:\nη = (π P r⁴) / (8 V l).\n\n3. FORMULA / PRINCIPLE:\nFractional error Δη/η = ΔP/P + 4(Δr/r) + ΔV/V + Δl/l.\n\n4. STEP-BY-STEP SOLUTION:\n1. In Poiseuille's formula, the radius r appears to the fourth power (r⁴).\n2. The relative error contribution from radius is 4 × (Δr/r).\n3. Because of the factor of 4, any small uncertainty in measuring the tiny capillary radius is multiplied fourfold.\n4. Therefore, radius measurement contributes the greatest fractional error to viscosity.\n\n5. FINAL ANSWER:\nOption A: Radius of the capillary tube (r)\n\n6. QUICK TIP:\nNEET Experimental Insight: Highest power = greatest error contributor. r⁴ contributes 4 × (Δr/r)!",
    "solutionStructured": {
      "concept": "Dominant error contribution in Poiseuille's viscosity equation.",
      "given": "η = (π P r⁴) / (8 V l).",
      "formula": "Fractional error Δη/η = ΔP/P + 4(Δr/r) + ΔV/V + Δl/l.",
      "stepByStep": "1. In Poiseuille's formula, the radius r appears to the fourth power (r⁴).\n2. The relative error contribution from radius is 4 × (Δr/r).\n3. Because of the factor of 4, any small uncertainty in measuring the tiny capillary radius is multiplied fourfold.\n4. Therefore, radius measurement contributes the greatest fractional error to viscosity.",
      "finalAnswer": "Option A: Radius of the capillary tube (r)",
      "whyOtherOptionsWrong": "Options B, C, and D all appear to power 1, so their errors are not magnified by a factor of 4."
    },
