    "explanation": "1. CONCEPT:\nError propagation in prism formula using differentiation with respect to minimum deviation.\n\n2. GIVEN:\nA = 60°, δ_m = 30.0°, Δδ_m = 0.6° = 0.6 × 0.0175 rad = 0.0105 rad.\n\n3. FORMULA / PRINCIPLE:\nμ = sin((A + δ_m)/2) / sin(A/2) => dμ/μ = cot((A + δ_m)/2) × (dδ_m / 2).\n\n4. STEP-BY-STEP SOLUTION:\n1. Mean angle: (A + δ_m)/2 = (60° + 30°)/2 = 45°.\n2. Differentiating μ = sin((A + δ_m)/2) / sin(A/2):\n   dμ = cos((A + δ_m)/2) · (dδ_m / 2) / sin(A/2).\n3. Dividing by μ gives the fractional error:\n   dμ / μ = cot((A + δ_m)/2) × (dδ_m / 2) = cot 45° × (dδ_m / 2).\n4. Since cot 45° = 1:\n   dμ / μ = 1 × (dδ_m / 2).\n5. Convert dδ_m to radians: dδ_m = 0.6° = 0.6 × 0.0175 rad = 0.0105 rad.\n6. Fractional error = 0.0105 / 2 = 0.00525.\n7. Percentage error = 0.00525 × 100% ≈ 0.52%.\n\n5. FINAL ANSWER:\nOption A: 0.52%\n\n6. QUICK TIP:\nNEET Golden Formula: For minimum deviation, dμ/μ = cot((A+δ_m)/2) × (dδ_m / 2). At 45°, cot 45° = 1 => % error = 0.5 × (dδ_m in rad) × 100% = 0.52%!",
