    "question": "The Reynolds number Re governing fluid flow in a pipe of diameter d is given by Re = (ρ v d) / η, where ρ is density, v is flow speed, and η is viscosity. If the flow speed v increases by 10% and the pipe diameter d decreases by 10% (with ρ and η unchanged), the percentage change in Reynolds number is:",
    "options": {
      "A": "Decreases by 1%",
      "B": "Increases by 1%",
      "C": "Remains unchanged (0%)",
      "D": "Decreases by 2%"
    },
